WITH flattened_attrs AS (SELECT id, plan, tier_limits, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, SLICE(tier_limits, 1, 2) AS first_two_limits, ARRAY_MIN(tier_prices) AS lowest_price, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices FROM price_tiers) SELECT *, NTILE(3) OVER w_running AS lowest_price_bucket, MAX(lowest_price) OVER (PARTITION BY plan) AS plan_max_lowest_price, LAG(lowest_price, 1, 0) OVER w_running AS prev_lowest_price, ROW_NUMBER() OVER (PARTITION BY plan ORDER BY lowest_price DESC, id) AS event_seq, RANK() OVER (PARTITION BY plan ORDER BY lowest_price) AS lowest_price_rank FROM flattened_attrs WINDOW w_running AS (PARTITION BY plan ORDER BY lowest_price, id)
